const response = $input.first().json;
const tasks = response.tasks || [];
const now = Date.now();
const weekAgo = now - (7 * 24 * 60 * 60 * 1000);

// Métricas
let completed = [];
let created = [];
let overdue = [];
let inProgress = [];
let pending = [];

const listStats = {};
const assigneeStats = {};

for (const task of tasks) {
  const statusName = task.status?.status?.toLowerCase() || '';
  const listName = task.list?.name || 'N/A';
  const dueDate = task.due_date ? parseInt(task.due_date) : null;
  const dateCreated = task.date_created ? parseInt(task.date_created) : 0;
  const assignees = (task.assignees || []).map(a => a.username).join(', ') || 'N/A';

  // Stats por lista
  if (!listStats[listName]) listStats[listName] = { completed: 0, pending: 0, total: 0 };
  listStats[listName].total++;

  // Stats por responsável
  for (const a of (task.assignees || [])) {
    const name = a.username || 'N/A';
    if (!assigneeStats[name]) assigneeStats[name] = { completed: 0, total: 0 };
    assigneeStats[name].total++;
  }

  const entry = {
    name: task.name,
    list: listName,
    assignees,
    priority: task.priority?.priority || 'normal'
  };

  if (statusName.includes('complete') || statusName.includes('conclu') || statusName.includes('done')) {
    completed.push(entry);
    listStats[listName].completed++;
    for (const a of (task.assignees || [])) {
      const name = a.username || 'N/A';
      if (assigneeStats[name]) assigneeStats[name].completed++;
    }
  } else if (dueDate && dueDate < now) {
    overdue.push(entry);
    listStats[listName].pending++;
  } else if (statusName.includes('progress') || statusName.includes('andamento')) {
    inProgress.push(entry);
    listStats[listName].pending++;
  } else {
    pending.push(entry);
    listStats[listName].pending++;
  }

  if (dateCreated >= weekAgo) {
    created.push(entry);
  }
}

return [{
  json: {
    weekOf: new Date(weekAgo).toLocaleDateString('pt-BR'),
    weekEnd: new Date().toLocaleDateString('pt-BR'),
    metrics: {
      totalTasks: tasks.length,
      completedCount: completed.length,
      createdCount: created.length,
      overdueCount: overdue.length,
      inProgressCount: inProgress.length,
      pendingCount: pending.length,
      completionRate: tasks.length > 0 ? Math.round((completed.length / tasks.length) * 100) : 0
    },
    completed: completed.slice(0, 15),
    overdue: overdue.slice(0, 10),
    inProgress: inProgress.slice(0, 10),
    pending: pending.slice(0, 10),
    listStats,
    assigneeStats
  }
}];

